package main
import("encoding/json";"encoding/hex";"math/big";"os";"github.com/dominant-strategies/go-quai/common";"github.com/dominant-strategies/go-quai/p2p/pb";"github.com/dominant-strategies/go-quai/core/types")
var referenceRevision string
func main(){if referenceRevision!="33db82f2891b267ba898ca38bd2dd8bf75cbb072"{panic("reference pin")};rows:=[]interface{}{};for i,height:=range []uint64{0,1,4294967297}{id:=uint32(7+i*10);h:=common.HexToHash("0x1234");if height==0{h=common.HexToHash("0x53fc82ff80d79fb2f225ecc80fe9b5130dd9f1d248a6140f41096ce822fb10cd")};if height==1{h=common.HexToHash("0x14f6d483600bb9730eddb66534840e28d4bba2020d57a8f957cb470c23ddc9e9")};blockReq,e:=pb.EncodeQuaiRequest(id,common.Location{0,0},new(big.Int).SetUint64(height),&types.WorkObjectBlockView{});if e!=nil{panic(e)};req,e:=pb.EncodeQuaiRequest(id,common.Location{0,0},new(big.Int).SetUint64(height),common.Hash{});if e!=nil{panic(e)};present,e:=pb.EncodeQuaiResponse(id,common.Location{0,0},(*common.Hash)(nil),&h);if e!=nil{panic(e)};blockAbsent,e:=pb.EncodeQuaiResponse(id,common.Location{0,0},&types.WorkObjectBlockView{},nil);if e!=nil{panic(e)};absent,e:=pb.EncodeQuaiResponse(id,common.Location{0,0},(*common.Hash)(nil),nil);if e!=nil{panic(e)};rows=append(rows,map[string]interface{}{"id":id,"height":height,"hash":h.Hex(),"block_absent_response":"0x"+hex.EncodeToString(blockAbsent),"block_request":"0x"+hex.EncodeToString(blockReq),"request":"0x"+hex.EncodeToString(req),"present_response":"0x"+hex.EncodeToString(present),"absent_response":"0x"+hex.EncodeToString(absent)})};json.NewEncoder(os.Stdout).Encode(map[string]interface{}{"reference_revision":referenceRevision,"vectors":rows})}
